Boolean run_safe_is_active (void)
{
  Boolean cur_state ;
  
  cur_state = run_safe_entry.run_safe_state;

  #if DBG_RUN_SAFE == 1  
    if(cur_state)
      {
        dbg_tx_text("\r\nRunSafe Active") ;
      }
    else
      {
        dbg_tx_text("\r\nRunSafe Not Active") ;
      }
  #endif 


  return (cur_state) ; 
}

